//! 🪆️ The paged clone owner composes actual child quotes without changing their currencies.
use super::*;
pub(crate) fn nested_retained_clone_grant(grant:RetainedCloneGrant)->Result<RetainedCloneGrant,ValueError>{Ok(RetainedCloneGrant{maximum_depth:grant.maximum_depth.checked_sub(1).ok_or_else(||ValueError::literal(ValueRefusalKind::DepthLimit,"paged clone child depth is absent"))?,..grant})}
pub(crate) fn nested_retained_clone_demands<T:RetireOwned+Send+Sync+'static,C:PagedCloneElement<T>>(child:&C,source:RetainedCloneRef<'_,T>,body:usize,work:u64)->Result<RetirementDemand,ValueError>{let mut d=child.advance_demands(source,body,work)?;d.depth=d.depth.checked_add(1).ok_or_else(||ValueError::invariant("paged clone quote depth overflow"))?;Ok(d)}
pub(crate) fn nested_retained_clone_take_demands<T:RetireOwned+Send+Sync+'static,C:PagedCloneElement<T>>(child:&C)->Result<RetirementDemand,ValueError>{let mut d=child.take_demand()?;d.depth=d.depth.checked_add(1).ok_or_else(||ValueError::invariant("paged clone take depth overflow"))?;Ok(d)}
pub(crate) fn nested_retained_clone_close_demands<T:RetireOwned+Send+Sync+'static,C:PagedCloneElement<T>>(child:&C,body:usize)->Result<RetirementDemand,ValueError>{let mut d=child.close_demands(body)?;d.depth=d.depth.checked_add(1).ok_or_else(||ValueError::invariant("paged clone close depth overflow"))?;Ok(d)}
pub(crate) fn child_start_demand<T:RetireOwned+Send+Sync+'static,C:PagedCloneElement<T>>(child:&C)->Result<RetirementDemand,ValueError>{if child.close_started(){Ok(RetirementDemand{copy_bytes:std::mem::size_of::<bool>(),depth:1,..Default::default()})}else{child.begin_close_demand()}}
pub(crate) fn start_child_close<T:RetireOwned+Send+Sync+'static,C:PagedCloneElement<T>>(child:&mut C,flag:&mut bool,effect:&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome<RetainedCloneProgress>{if !child.close_started(){return child.begin_close_paid(effect)}crate::start_retained_close(flag,effect)}
